<body>
  <header>
    <div class="wrap nav">
      <a href="#" class="logo"><i></i>Halo</a>
      <nav class="links"><a href="#produit">Produit</a><a href="#tarifs">Tarifs</a><a href="#clients">Clients</a><a href="#">Documentation</a></nav>
