<style>
  :root {
    --paper: #f4f1ea; --ink: #1a1814; --muted: #77716a; --line: #d9d3c7; --clay: #b4532a;
    --display: "Fraunces", Georgia, serif; --sans: "Manrope", system-ui, sans-serif;
  }
  * { box-sizing: border-box; margin: 0; }
  body { background: var(--paper); color: var(--ink); font: 400 16px/1.65 var(--sans); -webkit-font-smoothing: antialiased; }
  a { color: inherit; text-decoration: none; }
  .wrap { width: min(1240px, 100% - 48px); margin-inline: auto; }
  .label { font-size: 12px; letter-spacing: .16em; text-transform: uppercase; color: var(--muted); }

  header { display: flex; justify-content: space-between; align-items: center; padding: 28px 0; }
  .brand { font-family: var(--display); font-size: 22px; letter-spacing: -.02em; }
