  header nav a:hover::after { right: 0; }

  .hero { padding: 120px 0 80px; border-bottom: 1px solid var(--line); }
  .hero h1 { font-family: var(--display); font-weight: 300; font-size: clamp(56px, 10.5vw, 168px); line-height: .92; letter-spacing: -.055em; }
  .hero h1 em { font-style: italic; color: var(--clay); }
  .hero-foot { margin-top: 64px; display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 32px; align-items: end; }
  .hero-foot p { max-width: 340px; color: var(--muted); }
  .scroll { justify-self: end; display: inline-flex; align-items: center; gap: 12px; font-size: 14px; }
  .scroll i { width: 44px; height: 44px; border: 1px solid var(--ink); border-radius: 50%; display: grid; place-items: center; font-style: normal; transition: background .3s, color .3s; }
  .scroll:hover i { background: var(--ink); color: var(--paper); }

  section { padding: 110px 0; }
  .split { display: grid; grid-template-columns: 1fr 2fr; gap: 48px; }
  .split h2 { font-family: var(--display); font-weight: 400; font-size: clamp(34px, 4vw, 54px); line-height: 1.04; letter-spacing: -.03em; }

  .work { display: grid; grid-template-columns: repeat(12, 1fr); gap: 28px 24px; margin-top: 64px; }
