  .f3 { background: linear-gradient(180deg, #e9e4d8 0 50%, #1a1814 50%); }
  .f3::after { content: "N°"; position: absolute; inset: auto 24px 24px auto; font-family: var(--display); font-size: 96px; color: #f4f1ea; line-height: 1; }
  .f4 { background: conic-gradient(from 120deg at 60% 55%, #d8cfbf, #8c7b66, #d8cfbf); }
  .meta { display: flex; justify-content: space-between; margin-top: 14px; font-size: 14px; }
  .meta span { color: var(--muted); }

  .services { margin-top: 24px; border-top: 1px solid var(--ink); }
  .service { display: grid; grid-template-columns: 80px 1.2fr 1fr; gap: 24px; padding: 30px 0; border-bottom: 1px solid var(--line); align-items: baseline; transition: padding .35s ease; }
  .service:hover { padding-left: 12px; }
  .service small { color: var(--muted); font-size: 13px; }
  .service h3 { font-family: var(--display); font-weight: 400; font-size: clamp(26px, 3vw, 38px); letter-spacing: -.02em; }
  .service p { color: var(--muted); font-size: 15px; }

  .numbers { display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid var(--line); }
  .numbers div { padding: 40px 0 0; }
  .numbers strong { font-family: var(--display); font-weight: 300; font-size: clamp(56px, 7vw, 96px); letter-spacing: -.05em; line-height: 1; display: block; }
  .numbers span { color: var(--muted); font-size: 14px; }

  .contact { background: var(--ink); color: var(--paper); border-radius: 10px; padding: 96px 56px; }
  .contact .label { color: #a39d93; }
  .contact a.big { display: inline-block; margin-top: 18px; font-family: var(--display); font-weight: 300; font-size: clamp(40px, 7.5vw, 112px); letter-spacing: -.045em; line-height: 1; border-bottom: 1px solid #4a463f; padding-bottom: 8px; transition: color .3s, border-color .3s; }
  .contact a.big:hover { color: #e8b48e; border-color: #e8b48e; }
  .contact-foot { margin-top: 64px; display: flex; flex-wrap: wrap; gap: 48px; font-size: 14px; color: #a39d93; }

  footer { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 16px; padding: 40px 0 56px; font-size: 13px; color: var(--muted); }

  @media (max-width: 900px) {
