    .service { grid-template-columns: 48px 1fr; } .service p { grid-column: 2; }
    .contact { padding: 64px 28px; }
  }
</style>
</head>
<body>
  <div class="wrap">
    <header>
      <a class="brand" href="#">Atelier Nord<sup>®</sup></a>
      <nav><a href="#travaux">Travaux</a><a href="#services">Services</a><a href="#studio">Studio</a><a href="#contact">Contact</a></nav>
