<style>
  :root { --bg: #07080b; --panel: #0f1116; --line: #1d2028; --text: #f2f3f5; --muted: #8b90a0; --lime: #c8f560; --sky: #7cc4ff; --font: "Space Grotesk", system-ui, sans-serif; }
  * { box-sizing: border-box; margin: 0; }
