  .tag { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; color: var(--muted); }
  .tag::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--lime); box-shadow: 0 0 12px var(--lime); }
  h1 { margin-top: 22px; font-size: clamp(44px, 6.6vw, 84px); line-height: .98; letter-spacing: -.05em; font-weight: 600; }
  h1 span { color: var(--lime); }
  .lead { margin-top: 22px; max-width: 470px; color: var(--muted); font-size: 18px; }
  .stores { margin-top: 36px; display: flex; flex-wrap: wrap; gap: 12px; }
