  .grid { margin-top: 56px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line); border: 1px solid var(--line); border-radius: 24px; overflow: hidden; }
  .feat { background: var(--bg); padding: 34px; min-height: 250px; display: flex; flex-direction: column; gap: 12px; transition: background .3s; }
  .feat:hover { background: var(--panel); }
