  .feat p { color: var(--muted); font-size: 15px; }

  .stories { padding: 96px 0; }
  .quotes { margin-top: 48px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
  .q { padding: 28px; border-radius: 22px; background: var(--panel); border: 1px solid var(--line); display: flex; flex-direction: column; gap: 20px; }
  .q p { font-size: 17px; line-height: 1.5; }
  .q footer { margin-top: auto; font-size: 13px; color: var(--muted); }

  .download { margin-bottom: 80px; padding: 72px 40px; border-radius: 32px; text-align: center; background: radial-gradient(80% 120% at 50% 100%, rgba(200,245,96,.22), transparent 60%), var(--panel); border: 1px solid var(--line); }
  .download h2 { font-size: clamp(36px, 5.5vw, 64px); letter-spacing: -.045em; line-height: 1; font-weight: 600; }
  .download p { margin: 16px auto 0; max-width: 440px; color: var(--muted); }
  .download .stores { justify-content: center; }
  .foot { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 16px; padding: 32px 0 48px; border-top: 1px solid var(--line); font-size: 13px; color: var(--muted); }

  @media (max-width: 900px) {
    header nav { display: none; }
    .hero { grid-template-columns: 1fr; text-align: left; }
    .phone { width: 260px; margin-top: 24px; }
