<style>
  :root {
    --bg: #070b16; --panel: #0e1424; --panel-2: #121a2e; --line: rgba(255,255,255,.08); --ink: #eef2ff; --muted: #8b93ad;
    --lime: #c6f432; --lime-ink: #10170a; --blue: #5b8cff; --radius: 18px;
    --sans: "Manrope", system-ui, sans-serif; --mono: "JetBrains Mono", ui-monospace, monospace;
  }
  * { box-sizing: border-box; margin: 0; }
  body { background: var(--bg); color: var(--ink); font: 400 16px/1.6 var(--sans); -webkit-font-smoothing: antialiased; overflow-x: hidden; }
  a { color: inherit; text-decoration: none; }
  .wrap { width: min(1160px, 100% - 40px); margin-inline: auto; }
  .btn { display: inline-flex; align-items: center; gap: 8px; height: 46px; padding: 0 22px; border-radius: 999px; font-weight: 700; font-size: 15px; transition: transform .2s, box-shadow .2s; }
  .btn-lime { background: var(--lime); color: var(--lime-ink); box-shadow: 0 10px 30px -10px rgba(198,244,50,.55); }
