  .logo i { width: 22px; height: 22px; border-radius: 50%; border: 2px solid var(--lime); position: relative; }
  .logo i::after { content: ""; position: absolute; width: 7px; height: 7px; border-radius: 50%; background: var(--lime); top: -4px; right: -3px; }
  .links { display: flex; gap: 28px; font-size: 14px; color: var(--muted); }
  .links a:hover { color: var(--ink); }
  .hero { position: relative; padding: 96px 0 72px; }
