  .hero .wrap { position: relative; display: grid; grid-template-columns: 1.05fr .95fr; gap: 56px; align-items: center; }
  h1 { font-size: clamp(40px, 5.6vw, 68px); line-height: 1.02; letter-spacing: -.035em; font-weight: 800; margin-top: 18px; }
  h1 em { font-style: normal; color: var(--lime); }
  .lead { margin-top: 22px; font-size: 18px; color: var(--muted); max-width: 520px; }
  .cta { display: flex; gap: 12px; margin-top: 32px; flex-wrap: wrap; }
  .trust { display: flex; gap: 22px; margin-top: 36px; font-size: 13px; color: var(--muted); flex-wrap: wrap; }
  .trust b { color: var(--ink); font-weight: 700; }
  .card-stack { position: relative; height: 460px; }
  .bank-card { position: absolute; width: 340px; height: 214px; border-radius: 22px; padding: 24px; display: flex; flex-direction: column; justify-content: space-between; box-shadow: 0 40px 80px -30px rgba(0,0,0,.8); }
  .bank-card.one { top: 30px; right: 10px; background: linear-gradient(135deg, #1b2a55, #0d1430 60%), #0d1430; border: 1px solid rgba(255,255,255,.12); transform: rotate(-6deg); }
  .bank-card.two { top: 150px; left: 0; background: linear-gradient(135deg, var(--lime), #8fd61c); color: var(--lime-ink); transform: rotate(5deg); }
  .bank-card .chip { width: 40px; height: 30px; border-radius: 7px; background: linear-gradient(135deg, #f5d27a, #b8913b); }
  .bank-card .num { font-family: var(--mono); letter-spacing: .14em; font-size: 15px; }
  .bank-card .row { display: flex; justify-content: space-between; align-items: end; font-size: 12px; opacity: .85; }
  .widget { position: absolute; right: 0; bottom: 0; width: 280px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; box-shadow: 0 30px 60px -30px rgba(0,0,0,.9); }
  .widget p { font-size: 12px; color: var(--muted); }
  .widget strong { display: block; font-size: 26px; letter-spacing: -.02em; margin-top: 4px; }
