  .bars span { flex: 1; border-radius: 4px 4px 2px 2px; background: rgba(91,140,255,.35); }
  .bars span:last-child { background: var(--lime); }
  section { padding: 88px 0; }
  .center { text-align: center; max-width: 680px; margin-inline: auto; }
