  .checks li::before { content: "✓"; flex: none; width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; background: rgba(198,244,50,.14); color: var(--lime); font-size: 12px; font-weight: 800; margin-top: 2px; }
  .checks b { color: var(--ink); font-weight: 600; }
  .stats { display: grid; grid-template-columns: repeat(4, 1fr); border: 1px solid var(--line); border-radius: 22px; overflow: hidden; }
  .stats div { padding: 34px 28px; border-right: 1px solid var(--line); }
  .stats div:last-child { border-right: 0; }
  .stats strong { display: block; font-size: 40px; letter-spacing: -.03em; font-weight: 800; }
  .stats span { color: var(--muted); font-size: 14px; }
  .pricing { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 52px; }
  .plan { border: 1px solid var(--line); border-radius: 22px; padding: 30px; background: var(--panel); display: flex; flex-direction: column; }
  .plan.hot { background: linear-gradient(180deg, rgba(198,244,50,.08), transparent 40%), var(--panel); border-color: rgba(198,244,50,.45); }
  .plan h3 { font-size: 16px; }
  .plan .price { font-size: 42px; font-weight: 800; letter-spacing: -.03em; margin: 14px 0 4px; }
  .plan .price small { font-size: 15px; color: var(--muted); font-weight: 500; }
  .plan ul { margin: 22px 0 28px; padding: 0; display: grid; gap: 10px; color: var(--muted); font-size: 14.5px; flex: 1; }
  .plan li { list-style: none; } .plan li::before { content: "— "; color: var(--lime); }
  .final { margin: 0 auto 88px; border-radius: 28px; padding: 72px 40px; text-align: center; background: radial-gradient(60% 80% at 50% 0%, rgba(198,244,50,.18), transparent 70%), var(--panel); border: 1px solid var(--line); }
