  .steps { background: var(--paper); border: 1px solid var(--line); border-radius: 28px; padding: 48px; }
  .step { display: grid; grid-template-columns: 44px 1fr; gap: 16px; padding: 18px 0; border-bottom: 1px solid var(--line); }
  .step:last-child { border-bottom: 0; }
  .step span { font-family: var(--serif); font-size: 28px; color: var(--green); }
  .step p { color: var(--muted); font-size: 15px; }
  .quote { text-align: center; max-width: 820px; margin: 0 auto; }
