  .quote small { display: block; margin-top: 18px; color: var(--muted); font-size: 14px; }
  .news { background: var(--green); color: #eef3e8; border-radius: 28px; padding: 56px; display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: center; }
