  .links { display: flex; gap: 30px; color: var(--muted); font-size: 14px; } .links a:hover { color: var(--ink); }
  .btn { display: inline-flex; align-items: center; gap: 8px; height: 46px; padding: 0 22px; border-radius: 12px; font-weight: 500; font-size: 15px; transition: transform .2s, opacity .2s; }
