  .pill { position: relative; display: inline-flex; gap: 10px; align-items: center; border: 1px solid var(--line); background: rgba(255,255,255,.04); border-radius: 999px; padding: 6px 14px 6px 6px; font-size: 13px; color: var(--muted); }
  .pill b { background: linear-gradient(90deg, var(--a), var(--b)); color: #fff; border-radius: 999px; padding: 2px 10px; font-weight: 500; font-size: 12px; }
