  .chat { padding: 22px; display: flex; flex-direction: column; gap: 14px; }
  .msg { max-width: 78%; padding: 12px 15px; border-radius: 14px; font-size: 14px; line-height: 1.5; }
  .msg.user { background: rgba(255,255,255,.06); align-self: flex-start; border-bottom-left-radius: 4px; }
  .msg.bot { align-self: flex-end; background: linear-gradient(135deg, rgba(139,92,246,.28), rgba(34,211,238,.18)); border: 1px solid rgba(139,92,246,.35); border-bottom-right-radius: 4px; }
  .msg small { display: block; margin-top: 6px; font-size: 11px; color: var(--muted); }
  .typing { align-self: flex-end; display: flex; gap: 4px; padding: 12px 14px; border-radius: 14px; background: rgba(255,255,255,.04); }
