  .typing span:nth-child(2) { animation-delay: .15s; } .typing span:nth-child(3) { animation-delay: .3s; }
  @keyframes blink { 50% { opacity: .2; } }
  .logos { display: flex; justify-content: center; flex-wrap: wrap; gap: 44px; margin-top: 60px; color: #5c5c68; font-family: var(--display); font-weight: 600; font-size: 18px; letter-spacing: -.02em; }
  section { padding: 96px 0; }
