  .tile h3 { font-family: var(--display); font-size: 20px; letter-spacing: -.02em; font-weight: 600; }
  .tile p { color: var(--muted); margin-top: 8px; font-size: 15px; }
  .w4 { grid-column: span 4; } .w2 { grid-column: span 2; } .w3 { grid-column: span 3; }
  .big { font-family: var(--display); font-size: 64px; font-weight: 600; letter-spacing: -.04em; margin-top: 18px; }
  .langs { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 20px; }
  .langs span { border: 1px solid var(--line); border-radius: 999px; padding: 4px 12px; font-size: 13px; color: var(--muted); }
  .flow { display: flex; align-items: center; gap: 10px; margin-top: 22px; flex-wrap: wrap; font-size: 13px; }
  .flow span { border: 1px solid var(--line); background: rgba(255,255,255,.03); border-radius: 10px; padding: 8px 12px; }
