  .tile.accent::after { content: ""; position: absolute; width: 260px; height: 260px; right: -80px; bottom: -120px; border-radius: 50%; background: radial-gradient(circle, rgba(139,92,246,.45), transparent 70%); }
  .steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; margin-top: 54px; counter-reset: s; }
