  .steps div::before { content: "0" counter(s); font-family: var(--display); color: var(--b); font-size: 14px; }
  .steps h3 { font-family: var(--display); font-size: 20px; margin-top: 10px; font-weight: 600; }
  .steps p { color: var(--muted); margin-top: 6px; }
