  .final::before { content: ""; position: absolute; inset: auto 0 -60%; height: 120%; background: radial-gradient(50% 50% at 50% 50%, rgba(34,211,238,.18), transparent 70%); }
  .final > * { position: relative; }
  footer { padding: 40px 0; color: var(--muted); font-size: 13px; border-top: 1px solid var(--line); margin-top: 90px; }
