      </div>
    </section>

    <section>
      <div class="sec-head"><span class="mono">Outils &amp; méthodes</span></div>
      <div class="skills"><span>Recherche utilisateur</span><span>Prototypage</span><span>Design systems</span><span>Figma</span><span>Framer</span><span>Accessibilité</span><span>Ateliers</span></div>
    </section>

    <div class="contact">
