          <tr><td>Verdure</td><td><span class="badge b-warn"><i></i>En attente</span></td><td>840 €</td></tr>
          <tr><td>Kalo</td><td><span class="badge b-danger"><i></i>En retard</span></td><td>2 100 €</td></tr>
        </tbody>
      </table></div>
    </section>
  </main>
</body>
</html>
