('7e0c0000-0000-4000-8000-000000000402', NULL, 'Kit UI Nuit', 'Kit sombre en verre dépoli pour tableaux de bord et outils IA : boutons lumineux, zone de prompt, contrôles segmentés, statistiques et notifications.', 'ui_kit', $tn$<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kit UI Nuit</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
  /* Kit Nuit — surfaces sombres en verre dépoli, accent lumineux. Idéal pour tableaux de bord et outils IA. */
  :root {
    --bg: #09090b; --panel: rgba(255,255,255,.04); --panel-strong: rgba(255,255,255,.07); --line: rgba(255,255,255,.09);
    --text: #fafafa; --muted: #a1a1aa; --accent: #8b5cf6; --accent-2: #22d3ee; --success: #4ade80; --danger: #f87171;
    --r: 12px; --font: "Manrope", system-ui, sans-serif;
  }
  * { box-sizing: border-box; margin: 0; }
  body { min-height: 100vh; background: radial-gradient(900px 500px at 15% -10%, rgba(139,92,246,.25), transparent 60%), radial-gradient(700px 400px at 100% 0%, rgba(34,211,238,.14), transparent 60%), var(--bg); color: var(--text); font: 400 14px/1.55 var(--font); -webkit-font-smoothing: antialiased; padding: 48px 20px; }
  .sheet { width: min(1000px, 100%); margin: 0 auto; display: grid; gap: 20px; }
  .sheet > header h1 { font-size: 28px; font-weight: 700; letter-spacing: -.03em; }
  .sheet > header p { color: var(--muted); }
  .glass { background: var(--panel); border: 1px solid var(--line); border-radius: 18px; padding: 24px; backdrop-filter: blur(16px); }
  h2 { font-size: 12px; text-transform: uppercase; letter-spacing: .14em; color: var(--muted); font-weight: 600; margin-bottom: 16px; }
  .row { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
  .cols { display: grid; grid-template-columns: 1.2fr 1fr; gap: 20px; }

  .btn { height: 40px; padding: 0 18px; border-radius: var(--r); border: 1px solid transparent; font: 600 14px var(--font); color: var(--text); cursor: pointer; display: inline-flex; align-items: center; gap: 8px; transition: transform .15s, box-shadow .2s, background .2s; }
  .btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  .btn-glow { background: linear-gradient(135deg, var(--accent), #6d28d9); box-shadow: 0 0 0 1px rgba(255,255,255,.12) inset, 0 10px 30px -10px rgba(139,92,246,.8); }
  .btn-glow:hover { transform: translateY(-1px); box-shadow: 0 0 0 1px rgba(255,255,255,.18) inset, 0 14px 36px -10px rgba(139,92,246,.95); }
  .btn-glass { background: var(--panel-strong); border-color: var(--line); } .btn-glass:hover { background: rgba(255,255,255,.1); }
  .btn-outline { border-color: rgba(139,92,246,.6); color: #c4b5fd; background: rgba(139,92,246,.08); }
  .btn-icon { width: 40px; padding: 0; justify-content: center; }

  .input-wrap { display: flex; align-items: center; gap: 10px; height: 44px; padding: 0 14px; border-radius: var(--r); background: rgba(0,0,0,.35); border: 1px solid var(--line); transition: border-color .2s, box-shadow .2s; }
  .input-wrap:focus-within { border-color: rgba(139,92,246,.7); box-shadow: 0 0 0 4px rgba(139,92,246,.15); }
  .input-wrap input { flex: 1; min-width: 0; background: none; border: 0; outline: 0; color: var(--text); font: inherit; }
  .input-wrap input::placeholder { color: #71717a; }
  .input-wrap kbd { font: 600 11px var(--font); color: var(--muted); padding: 2px 7px; border-radius: 6px; border: 1px solid var(--line); }
  .prompt { border-radius: 16px; background: rgba(0,0,0,.35); border: 1px solid var(--line); padding: 14px; }
  .prompt textarea { width: 100%; min-height: 72px; resize: none; background: none; border: 0; outline: 0; color: var(--text); font: inherit; font-size: 15px; }
  .prompt .row { justify-content: space-between; }
  .chip { height: 30px; padding: 0 12px; border-radius: 999px; background: var(--panel-strong); border: 1px solid var(--line); font-size: 12px; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; }
  .chip.on { color: var(--text); border-color: rgba(34,211,238,.5); background: rgba(34,211,238,.1); }

  .stat { padding: 18px; border-radius: 14px; background: var(--panel); border: 1px solid var(--line); }
  .stat small { color: var(--muted); } .stat strong { display: block; font-size: 26px; font-weight: 700; letter-spacing: -.03em; }
  .up { color: var(--success); font-size: 12px; } .down { color: var(--danger); font-size: 12px; }
  .stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
  .progress { height: 8px; border-radius: 999px; background: rgba(255,255,255,.08); overflow: hidden; margin-top: 10px; }
  .progress i { display: block; height: 100%; width: 68%; border-radius: inherit; background: linear-gradient(90deg, var(--accent), var(--accent-2)); }

  .seg { display: inline-flex; padding: 4px; border-radius: 12px; background: rgba(0,0,0,.35); border: 1px solid var(--line); }
  .seg button { border: 0; background: none; color: var(--muted); font: 600 13px var(--font); padding: 7px 14px; border-radius: 9px; cursor: pointer; }
  .seg button[aria-selected="true"] { background: var(--panel-strong); color: var(--text); box-shadow: 0 0 0 1px var(--line) inset; }
  .toggle { width: 42px; height: 24px; border-radius: 999px; background: linear-gradient(135deg, var(--accent), var(--accent-2)); position: relative; }
  .toggle::after { content: ""; position: absolute; top: 3px; right: 3px; width: 18px; height: 18px; border-radius: 50%; background: #fff; }
  .toast { display: flex; gap: 12px; align-items: center; padding: 14px 16px; border-radius: 14px; background: rgba(24,24,27,.85); border: 1px solid var(--line); box-shadow: 0 20px 40px -20px rgba(0,0,0,.8); }
  .toast i { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; background: rgba(74,222,128,.15); color: var(--success); font-style: normal; }
  .toast span { color: var(--muted); }
  @media (max-width: 820px) { .cols, .stats { grid-template-columns: 1fr; } }
</style>
</head>
<body>
  <main class="sheet">
    <header><h1>Kit UI Nuit</h1><p>Verre dépoli, contrastes doux et accents lumineux.</p></header>
    <section class="glass"><h2>Boutons</h2>
      <div class="row"><button class="btn btn-glow">Générer ✦</button><button class="btn btn-glass">Dupliquer</button><button class="btn btn-outline">Mettre à niveau</button><button class="btn btn-glass btn-icon" aria-label="Partager">↗</button></div>
    </section>
    <div class="cols">
      <section class="glass"><h2>Saisie</h2>
        <div style="display:grid;gap:14px">
          <div class="input-wrap"><span aria-hidden="true">⌕</span><input placeholder="Rechercher un projet…" aria-label="Rechercher"><kbd>⌘K</kbd></div>
          <div class="prompt"><textarea aria-label="Message" placeholder="Décrivez ce que vous voulez créer…"></textarea>
            <div class="row"><div class="row" style="gap:8px"><span class="chip on">◆ Raisonnement</span><span class="chip">+ Fichier</span></div><button class="btn btn-glow btn-icon" aria-label="Envoyer">↑</button></div>
          </div>
        </div>
      </section>
      <section class="glass"><h2>Contrôles</h2>
        <div style="display:grid;gap:18px">
          <div class="seg" role="tablist"><button role="tab" aria-selected="true">Jour</button><button role="tab" aria-selected="false">Semaine</button><button role="tab" aria-selected="false">Mois</button></div>
          <div class="row" style="justify-content:space-between"><span>Synchronisation automatique</span><span class="toggle" role="img" aria-label="Activé"></span></div>
          <div><div class="row" style="justify-content:space-between"><span>Quota utilisé</span><span style="color:var(--muted)">68 %</span></div><div class="progress"><i></i></div></div>
        </div>
      </section>
    </div>
    <section class="glass"><h2>Statistiques</h2>
      <div class="stats">
        <div class="stat"><small>Requêtes</small><strong>48 920</strong><span class="up">▲ 12,8 %</span></div>
        <div class="stat"><small>Latence moyenne</small><strong>182 ms</strong><span class="up">▲ 4,1 %</span></div>
        <div class="stat"><small>Erreurs</small><strong>0,21 %</strong><span class="down">▼ 0,05 pt</span></div>
      </div>
    </section>
    <div class="toast"><i>✓</i><div><b>Déploiement réussi</b><br><span>Votre site est en ligne depuis 12 secondes.</span></div></div>
  </main>
</body>
</html>
$tn$, 'html', 'TechNova', 'TechNova Studio', 'technova', true, true, true, false, 'public'),
('7e0c0000-0000-4000-8000-000000000403', NULL, 'Parcours UX — Onboarding mobile', 'Quatre écrans de téléphone : promesse, choix de l''objectif, permission expliquée et confirmation, avec notes UX sur chaque étape. Plus Jakarta Sans.', 'ui_kit', $tn$<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Parcours UX — Onboarding mobile</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
  :root { --bg: #eef0f6; --ink: #121527; --muted: #6a6f86; --line: #e3e5ee; --brand: #4f46e5; --brand-2: #8b5cf6; --mint: #10b981; --sans: "Plus Jakarta Sans", system-ui, sans-serif; }
  * { box-sizing: border-box; margin: 0; }
  body { background: var(--bg); color: var(--ink); font: 400 15px/1.55 var(--sans); -webkit-font-smoothing: antialiased; }
  .intro { max-width: 1180px; margin: 0 auto; padding: 48px 24px 8px; display: flex; justify-content: space-between; align-items: end; gap: 20px; flex-wrap: wrap; }
  .intro p.k { font-size: 12px; letter-spacing: .16em; text-transform: uppercase; color: var(--brand); font-weight: 700; }
  .intro h1 { font-size: clamp(28px, 3.4vw, 40px); letter-spacing: -.03em; font-weight: 800; margin-top: 6px; }
  .intro .d { color: var(--muted); max-width: 460px; }
  .flow { max-width: 1180px; margin: 0 auto; padding: 28px 24px 56px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; align-items: start; }
  .step-label { display: flex; align-items: center; gap: 8px; font-size: 12.5px; font-weight: 700; color: var(--muted); margin-bottom: 12px; }
  .step-label b { width: 22px; height: 22px; border-radius: 50%; background: var(--ink); color: #fff; display: grid; place-items: center; font-size: 11px; }
  .phone { background: #fff; border-radius: 38px; padding: 10px; box-shadow: 0 30px 60px -30px rgba(18,21,39,.35), 0 0 0 1px rgba(18,21,39,.06); }
  .screen { position: relative; border-radius: 30px; overflow: hidden; height: 560px; display: flex; flex-direction: column; background: #fff; }
  .status { height: 34px; display: flex; justify-content: space-between; align-items: center; padding: 0 20px; font-size: 12px; font-weight: 700; }
  .status i { width: 70px; height: 20px; border-radius: 999px; background: var(--ink); }
  .pad { padding: 8px 22px 22px; display: flex; flex-direction: column; flex: 1; }
  .hero-art { height: 250px; margin: 6px 14px 0; border-radius: 26px; background: linear-gradient(160deg, #e0e7ff, #ede9fe 60%, #fce7f3); position: relative; overflow: hidden; }
  .hero-art .orb { position: absolute; width: 150px; height: 150px; border-radius: 50%; left: 50%; top: 50%; transform: translate(-50%, -50%); background: radial-gradient(circle at 35% 30%, #fff, #a5b4fc 30%, var(--brand) 70%); box-shadow: 0 30px 50px -20px rgba(79,70,229,.6); }
  .hero-art .chip { position: absolute; background: #fff; border-radius: 12px; padding: 6px 10px; font-size: 11px; font-weight: 700; box-shadow: 0 10px 20px -12px rgba(18,21,39,.4); }
  h2 { font-size: 24px; line-height: 1.15; letter-spacing: -.025em; font-weight: 800; margin-top: 22px; }
  .p { color: var(--muted); font-size: 14px; margin-top: 8px; }
  .dots { display: flex; gap: 6px; margin-top: auto; padding-top: 18px; }
  .dots span { width: 7px; height: 7px; border-radius: 999px; background: var(--line); }
  .dots span.on { width: 22px; background: var(--brand); }
  .btn { display: flex; align-items: center; justify-content: center; height: 50px; border-radius: 16px; font-weight: 700; font-size: 15px; margin-top: 16px; border: 0; width: 100%; cursor: pointer; font-family: inherit; }
  .btn.main { background: var(--ink); color: #fff; }
  .btn.alt { background: transparent; color: var(--muted); margin-top: 4px; height: 40px; }
  .choices { display: grid; gap: 10px; margin-top: 18px; }
  .choice { display: flex; align-items: center; gap: 12px; padding: 13px 14px; border: 1.5px solid var(--line); border-radius: 16px; font-weight: 600; font-size: 14px; }
  .choice i { width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; font-style: normal; font-size: 17px; background: #f4f5fa; }
  .choice small { display: block; font-weight: 500; color: var(--muted); font-size: 12px; }
  .choice.on { border-color: var(--brand); background: #f5f5ff; }
  .choice.on::after { content: "✓"; margin-left: auto; width: 22px; height: 22px; border-radius: 50%; background: var(--brand); color: #fff; display: grid; place-items: center; font-size: 12px; }
  .progress { height: 6px; border-radius: 999px; background: var(--line); margin-top: 6px; overflow: hidden; }
  .progress span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--brand), var(--brand-2)); }
  .back { display: flex; justify-content: space-between; align-items: center; font-size: 13px; color: var(--muted); font-weight: 600; }
  .perm { margin: 30px auto 0; width: 120px; height: 120px; border-radius: 36px; background: linear-gradient(145deg, #ecfdf5, #d1fae5); display: grid; place-items: center; position: relative; }
  .perm::before { content: ""; width: 46px; height: 54px; border-radius: 12px 12px 18px 18px; border: 4px solid var(--mint); border-top-width: 10px; }
  .perm b { position: absolute; top: 10px; right: 12px; width: 26px; height: 26px; border-radius: 50%; background: #ef4444; color: #fff; font-size: 12px; display: grid; place-items: center; box-shadow: 0 0 0 4px #fff; }
  .center { text-align: center; }
  .list { margin-top: 16px; display: grid; gap: 10px; }
  .list div { display: flex; gap: 10px; font-size: 13.5px; color: var(--muted); }
  .list div::before { content: "•"; color: var(--mint); font-weight: 800; }
  .done { margin: 36px auto 0; width: 110px; height: 110px; border-radius: 50%; background: radial-gradient(circle, #ecfdf5 55%, transparent 56%), conic-gradient(var(--mint), #34d399, #a7f3d0, var(--mint)); display: grid; place-items: center; }
  .done svg { width: 46px; height: 46px; }
  .summary { margin-top: 20px; background: #f7f8fc; border-radius: 16px; padding: 14px; display: grid; gap: 8px; font-size: 13px; }
  .summary div { display: flex; justify-content: space-between; } .summary span { color: var(--muted); }
  .notes { max-width: 1180px; margin: 0 auto; padding: 0 24px 64px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
  .notes div { font-size: 13px; color: var(--muted); border-top: 2px solid var(--ink); padding-top: 12px; }
  .notes b { display: block; color: var(--ink); font-size: 14px; margin-bottom: 4px; }
  @media (max-width: 1080px) { .flow, .notes { grid-template-columns: repeat(2, 1fr); } }
  @media (max-width: 600px) { .flow, .notes { grid-template-columns: 1fr; } }
</style>
</head>
<body>
<div class="intro">
  <div><p class="k">Kit UX · Parcours</p><h1>Onboarding mobile en 4 écrans</h1></div>
  <p class="d">Un parcours d'accueil éprouvé : promesse, personnalisation, permission expliquée, confirmation. Chaque écran a une seule action principale.</p>
</div>

<div class="flow">
  <div>
    <p class="step-label"><b>1</b>Promesse</p>
    <div class="phone"><div class="screen">
      <div class="status"><span>9:41</span><i></i><span>100 %</span></div>
      <div class="hero-art"><span class="orb"></span><span class="chip" style="top:24px;left:18px">✦ Objectif atteint</span><span class="chip" style="bottom:26px;right:16px">+32 % ce mois</span></div>
      <div class="pad">
        <h2>Vos habitudes, enfin tenues.</h2>
        <p class="p">Un coach qui s'adapte à votre rythme, pas l'inverse.</p>
        <div class="dots"><span class="on"></span><span></span><span></span></div>
        <button class="btn main">Commencer</button>
        <button class="btn alt">J'ai déjà un compte</button>
      </div>
    </div></div>
  </div>

  <div>
    <p class="step-label"><b>2</b>Personnalisation</p>
    <div class="phone"><div class="screen">
      <div class="status"><span>9:41</span><i></i><span>100 %</span></div>
      <div class="pad">
        <div class="back"><span>← Retour</span><span>2 / 4</span></div>
        <div class="progress"><span style="width:50%"></span></div>
        <h2>Quel est votre objectif principal ?</h2>
        <p class="p">Nous adaptons vos rappels et vos conseils.</p>
        <div class="choices">
          <div class="choice on"><i>🧘</i><span>Mieux dormir<small>Routine du soir</small></span></div>
          <div class="choice"><i>🏃</i><span>Bouger plus<small>10 000 pas par jour</small></span></div>
          <div class="choice"><i>📚</i><span>Apprendre chaque jour<small>15 minutes de lecture</small></span></div>
        </div>
        <button class="btn main" style="margin-top:auto">Continuer</button>
      </div>
    </div></div>
  </div>

  <div>
    <p class="step-label"><b>3</b>Permission expliquée</p>
    <div class="phone"><div class="screen">
      <div class="status"><span>9:41</span><i></i><span>100 %</span></div>
      <div class="pad center">
        <div class="back"><span>← Retour</span><span>3 / 4</span></div>
        <div class="progress"><span style="width:75%"></span></div>
        <div class="perm"><b>1</b></div>
        <h2>Un rappel au bon moment</h2>
        <p class="p">Activez les notifications pour recevoir un seul rappel par jour, à l'heure que vous choisissez.</p>
        <div class="list" style="text-align:left"><div>Jamais de publicité</div><div>Désactivable à tout moment</div></div>
        <button class="btn main" style="margin-top:auto">Activer les rappels</button>
        <button class="btn alt">Plus tard</button>
      </div>
    </div></div>
  </div>

  <div>
    <p class="step-label"><b>4</b>Confirmation</p>
    <div class="phone"><div class="screen">
      <div class="status"><span>9:41</span><i></i><span>100 %</span></div>
      <div class="pad center">
        <div class="done"><svg viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></div>
        <h2>Tout est prêt, Adjoa !</h2>
        <p class="p">Votre programme « Mieux dormir » commence ce soir.</p>
        <div class="summary" style="text-align:left"><div><span>Objectif</span><b>Mieux dormir</b></div><div><span>Rappel</span><b>Chaque jour à 21:30</b></div><div><span>Durée</span><b>21 jours</b></div></div>
        <button class="btn main" style="margin-top:auto">Découvrir mon programme</button>
      </div>
    </div></div>
  </div>
</div>

<div class="notes">
  <div><b>Une promesse claire</b>Une phrase de bénéfice et un visuel, pas de liste de fonctionnalités.</div>
  <div><b>Progression visible</b>Barre et compteur rassurent sur la longueur du parcours.</div>
  <div><b>Permission contextualisée</b>On explique le bénéfice avant la boîte système, avec une sortie « Plus tard ».</div>
  <div><b>Récapitulatif final</b>L'utilisateur voit ce qui a été configuré et sait quoi faire ensuite.</div>
</div>
<script>
  document.querySelectorAll(".choice").forEach((c) => c.addEventListener("click", () => {
    document.querySelectorAll(".choice").forEach((x) => x.classList.toggle("on", x === c));
  }));
</script>
</body>
</html>
