<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
  :root { --bg: #f4f4f5; --panel: #fff; --ink: #09090b; --muted: #71717a; --line: #e4e4e7; --soft: #fafafa; --brand: #2563eb; --brand-soft: #eff6ff; --red: #dc2626; --green: #16a34a; --radius: 14px; --sans: "Inter", system-ui, sans-serif; }
  * { box-sizing: border-box; margin: 0; }
