  .card { background: var(--panel); border: 1px solid var(--line); border-radius: 20px; box-shadow: 0 1px 2px rgba(0,0,0,.04), 0 20px 40px -28px rgba(0,0,0,.25); }
  .auth { padding: 34px 32px; }
  .logo { width: 40px; height: 40px; border-radius: 12px; background: var(--ink); display: grid; place-items: center; color: #fff; font-weight: 700; }
  .auth h2 { font-size: 22px; letter-spacing: -.02em; margin-top: 18px; }
  .auth .sub { color: var(--muted); margin-top: 4px; }
  .social { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 24px; }
  .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 42px; border-radius: 10px; border: 1px solid var(--line); background: var(--panel); font: 500 14px var(--sans); cursor: pointer; color: var(--ink); padding: 0 14px; }
  .btn:hover { background: var(--soft); }
  .btn.primary { background: var(--ink); border-color: var(--ink); color: #fff; width: 100%; margin-top: 18px; }
  .btn.primary:hover { background: #27272a; }
  .btn.danger { color: var(--red); border-color: #fecaca; }
  .or { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 12px; margin: 22px 0 6px; }
  .or::before, .or::after { content: ""; flex: 1; height: 1px; background: var(--line); }
  label.field { display: grid; gap: 6px; margin-top: 14px; font-weight: 500; font-size: 13px; }
  .input { height: 42px; border-radius: 10px; border: 1px solid var(--line); padding: 0 12px; font: inherit; color: var(--ink); background: var(--panel); outline: none; transition: border-color .15s, box-shadow .15s; width: 100%; }
  .input:focus { border-color: var(--brand); box-shadow: 0 0 0 4px rgba(37,99,235,.12); }
