  .settings { display: grid; grid-template-columns: 200px 1fr; overflow: hidden; }
  .menu { border-right: 1px solid var(--line); padding: 16px 10px; background: var(--soft); display: grid; gap: 2px; align-content: start; }
  .menu a { padding: 8px 12px; border-radius: 8px; color: var(--muted); font-weight: 500; text-decoration: none; }
  .menu a.on { background: var(--panel); color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,.06); }
  .content { padding: 26px 28px; }
  .content h2 { font-size: 18px; letter-spacing: -.01em; }
  .content > p { color: var(--muted); margin-top: 2px; }
  .sect { border-top: 1px solid var(--line); margin-top: 22px; padding-top: 22px; display: grid; grid-template-columns: 220px 1fr; gap: 24px; }
  .sect h3 { font-size: 14px; } .sect h3 + p { color: var(--muted); font-size: 13px; margin-top: 4px; }
  .avatar { display: flex; align-items: center; gap: 14px; }
  .avatar span { width: 56px; height: 56px; border-radius: 50%; background: linear-gradient(135deg, #60a5fa, #a78bfa); display: grid; place-items: center; color: #fff; font-weight: 700; font-size: 18px; }
  .two { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
  .toggle { display: flex; justify-content: space-between; align-items: center; padding: 12px 0; border-bottom: 1px solid var(--line); }
  .toggle:last-child { border-bottom: 0; }
  .toggle small { display: block; color: var(--muted); font-size: 12.5px; }
  .switch { width: 38px; height: 22px; border-radius: 999px; background: var(--line); position: relative; flex: none; cursor: pointer; transition: background .2s; }
  .switch::after { content: ""; position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; box-shadow: 0 1px 2px rgba(0,0,0,.2); transition: transform .2s; }
  .switch.on { background: var(--brand); } .switch.on::after { transform: translateX(16px); }
  .session { display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; border: 1px solid var(--line); border-radius: 10px; margin-bottom: 8px; }
  .session small { display: block; color: var(--muted); font-size: 12px; }
  .pill { font-size: 11px; font-weight: 600; color: var(--green); background: #f0fdf4; border-radius: 999px; padding: 2px 8px; }
  .actions { display: flex; justify-content: end; gap: 8px; border-top: 1px solid var(--line); margin-top: 22px; padding-top: 18px; }
  .actions .btn.primary { width: auto; margin-top: 0; }
  .danger-zone { border: 1px solid #fecaca; background: #fef2f2; border-radius: 12px; padding: 14px 16px; display: flex; justify-content: space-between; align-items: center; gap: 12px; }
  .danger-zone small { display: block; color: #991b1b; opacity: .8; }
  .board > div, .content { min-width: 0; }
  @media (max-width: 1180px) { .board { grid-template-columns: 1fr; } .board > div:first-child { max-width: 440px; } }
  @media (max-width: 860px) { .settings { grid-template-columns: 1fr; } .menu { display: none; } .sect { grid-template-columns: 1fr; gap: 12px; } .two { grid-template-columns: 1fr; } }
</style>
</head>
<body>
<div class="intro"><p>Kit UX · Écrans de compte</p><h1>Connexion & paramètres <span>— états inclus</span></h1></div>

<div class="board">
  <div>
    <p class="tag">Connexion · avec erreur de validation</p>
    <form class="card auth" onsubmit="event.preventDefault()">
      <div class="logo">N</div>
      <h2>Bon retour parmi nous</h2>
      <p class="sub">Connectez-vous pour reprendre où vous en étiez.</p>
      <div class="social">
        <button class="btn" type="button"><svg width="16" height="16" viewBox="0 0 24 24"><path fill="#4285F4" d="M23 12.3c0-.8-.1-1.6-.2-2.3H12v4.4h6.2a5.3 5.3 0 0 1-2.3 3.5v2.9h3.7c2.2-2 3.4-5 3.4-8.5z"/><path fill="#34A853" d="M12 23.5c3.1 0 5.7-1 7.6-2.8l-3.7-2.9c-1 .7-2.4 1.1-3.9 1.1-3 0-5.5-2-6.4-4.7H1.8v3A11.5 11.5 0 0 0 12 23.5z"/><path fill="#FBBC05" d="M5.6 14.2a6.9 6.9 0 0 1 0-4.4v-3H1.8a11.5 11.5 0 0 0 0 10.4l3.8-3z"/><path fill="#EA4335" d="M12 4.7c1.7 0 3.2.6 4.4 1.7l3.3-3.3A11.5 11.5 0 0 0 1.8 6.8l3.8 3c.9-2.8 3.4-5.1 6.4-5.1z"/></svg>Google</button>
        <button class="btn" type="button"><svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor"><path d="M16.4 12.6c0-2.6 2.1-3.8 2.2-3.9a4.8 4.8 0 0 0-3.8-2c-1.6-.2-3.1.9-3.9.9-.8 0-2-.9-3.4-.9a5 5 0 0 0-4.2 2.6c-1.8 3.1-.5 7.7 1.3 10.2.8 1.2 1.8 2.6 3.1 2.6 1.3-.1 1.7-.8 3.3-.8 1.5 0 1.9.8 3.3.8 1.4 0 2.2-1.3 3-2.5a10 10 0 0 0 1.4-2.8 4.3 4.3 0 0 1-2.3-4.2zM13.9 4.9A4.4 4.4 0 0 0 14.9 1.7a4.5 4.5 0 0 0-2.9 1.5 4.2 4.2 0 0 0-1.1 3.1c1.1.1 2.2-.6 3-1.4z"/></svg>Apple</button>
      </div>
      <div class="or">ou avec votre e-mail</div>
      <label class="field">Adresse e-mail<input class="input" type="email" value="kofi@studio.africa"></label>
      <label class="field">Mot de passe<input class="input err" type="password" value="motdepasse"><span class="hint">Mot de passe incorrect. Il vous reste 4 essais.</span></label>
      <div class="row"><span class="check"><i>✓</i>Rester connecté</span><a href="#">Mot de passe oublié ?</a></div>
      <button class="btn primary" type="submit">Se connecter</button>
      <p class="foot">Pas encore de compte ? <a href="#">Créer un compte</a></p>
    </form>

    <p class="tag" style="margin-top:24px">Inscription · force du mot de passe</p>
    <form class="card auth" onsubmit="event.preventDefault()" style="padding-top:26px">
      <div class="two"><label class="field" style="margin-top:0">Prénom<input class="input" value="Adjoa"></label><label class="field" style="margin-top:0">Nom<input class="input" value="Mensah"></label></div>
      <label class="field">Mot de passe<input class="input" type="password" value="Ab9!correct-horse"><div class="strength"><span class="on"></span><span class="on"></span><span class="on"></span><span></span></div><span style="font-size:12px;color:var(--green);font-weight:400">Solide · ajoutez 2 caractères pour « Excellent »</span></label>
      <button class="btn primary" type="submit">Créer mon compte</button>
    </form>
  </div>

  <div>
    <p class="tag">Paramètres du compte</p>
    <div class="card settings">
      <nav class="menu"><a class="on" href="#">Profil</a><a href="#">Sécurité</a><a href="#">Notifications</a><a href="#">Facturation</a><a href="#">Équipe</a><a href="#">Intégrations</a></nav>
      <div class="content">
        <h2>Profil</h2><p>Ces informations sont visibles par les membres de votre équipe.</p>
        <div class="sect"><div><h3>Photo et nom</h3><p>Une photo carrée d'au moins 256 px.</p></div>
          <div><div class="avatar"><span>AM</span><button class="btn" type="button">Changer</button><button class="btn" type="button" style="border:0;color:var(--muted)">Retirer</button></div>
            <div class="two" style="margin-top:14px"><label class="field" style="margin-top:0">Nom affiché<input class="input" value="Adjoa Mensah"></label><label class="field" style="margin-top:0">Poste<input class="input" value="Product designer"></label></div></div></div>
        <div class="sect"><div><h3>Notifications</h3><p>Choisissez ce que vous recevez.</p></div>
          <div><div class="toggle"><span>Mentions et réponses<small>Quand quelqu'un vous mentionne.</small></span><span class="switch on" role="switch" aria-checked="true" tabindex="0"></span></div>
            <div class="toggle"><span>Résumé hebdomadaire<small>Chaque lundi à 8 h.</small></span><span class="switch on" role="switch" aria-checked="true" tabindex="0"></span></div>
            <div class="toggle"><span>Nouveautés produit<small>Au plus une fois par mois.</small></span><span class="switch" role="switch" aria-checked="false" tabindex="0"></span></div></div></div>
        <div class="sect"><div><h3>Sessions actives</h3><p>Déconnectez les appareils que vous ne reconnaissez pas.</p></div>
          <div><div class="session"><span>MacBook Pro · Chrome<small>Abidjan · maintenant</small></span><span class="pill">Cet appareil</span></div>
            <div class="session"><span>iPhone 15 · Application<small>Abidjan · il y a 2 h</small></span><button class="btn" type="button" style="height:32px">Déconnecter</button></div></div></div>
        <div class="sect"><div><h3>Zone sensible</h3><p>Action définitive.</p></div>
          <div class="danger-zone"><span><b>Supprimer le compte</b><small>Vos projets et fichiers seront effacés.</small></span><button class="btn danger" type="button">Supprimer</button></div></div>
        <div class="actions"><button class="btn" type="button">Annuler</button><button class="btn primary" type="button">Enregistrer</button></div>
      </div>
    </div>
  </div>
</div>
<script>
  document.querySelectorAll(".switch").forEach((s) => {
    const flip = () => { s.classList.toggle("on"); s.setAttribute("aria-checked", String(s.classList.contains("on"))); };
    s.addEventListener("click", flip);
    s.addEventListener("keydown", (e) => { if (e.key === " " || e.key === "Enter") { e.preventDefault(); flip(); } });
  });
</script>
</body>
</html>
