$tn$, 'html', 'TechNova', 'TechNova Studio', 'technova', true, true, true, false, 'public'),
('7e0c0000-0000-4000-8000-000000000902', NULL, 'Ledger — Console de facturation', 'Console claire de gestion des factures : résumé des encaissements, filtres par statut, tableau avec badges, panneau de détail, relance et historique. Geist × Geist Mono.', 'dashboard', $tn$<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Ledger — Console de facturation</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&family=Geist+Mono:wght@500&display=swap" rel="stylesheet">
<style>
  :root {
    --bg: #f7f7f5; --panel: #ffffff; --ink: #18181b; --muted: #71717a; --line: #e7e7e4; --soft: #f1f1ee;
    --accent: #0f766e; --accent-soft: #e6f4f2; --red: #b42318; --red-soft: #fdecea; --amber: #a15c07; --amber-soft: #fdf3e2; --blue: #1d4ed8; --blue-soft: #e8eefc;
    --radius: 12px; --sans: "Geist", system-ui, sans-serif; --mono: "Geist Mono", ui-monospace, monospace;
  }
  * { box-sizing: border-box; margin: 0; }
  body { background: var(--bg); color: var(--ink); font: 400 14px/1.5 var(--sans); -webkit-font-smoothing: antialiased; }
  a { color: inherit; text-decoration: none; }
  header.bar { height: 60px; background: var(--panel); border-bottom: 1px solid var(--line); display: flex; align-items: center; gap: 22px; padding: 0 24px; position: sticky; top: 0; z-index: 5; }
  .brand { font-weight: 700; font-size: 16px; display: flex; gap: 8px; align-items: center; }
  .brand i { width: 22px; height: 22px; border-radius: 6px; background: var(--ink); position: relative; }
  .brand i::after { content: ""; position: absolute; inset: 6px 5px; border-top: 2px solid #fff; border-bottom: 2px solid #fff; }
  .tabs { display: flex; gap: 4px; height: 100%; }
  .tabs a { display: flex; align-items: center; padding: 0 12px; color: var(--muted); font-weight: 500; border-bottom: 2px solid transparent; }
  .tabs a.on { color: var(--ink); border-color: var(--ink); }
  .tabs a:hover { color: var(--ink); }
  .bar .right { margin-left: auto; display: flex; align-items: center; gap: 10px; }
  .org { display: flex; align-items: center; gap: 8px; border: 1px solid var(--line); border-radius: 9px; padding: 5px 10px 5px 6px; font-weight: 500; }
  .org span { width: 24px; height: 24px; border-radius: 6px; background: var(--accent); color: #fff; display: grid; place-items: center; font-size: 11px; font-weight: 700; }
  main { max-width: 1240px; margin: 0 auto; padding: 28px 24px 48px; }
  .title { display: flex; justify-content: space-between; align-items: end; gap: 16px; flex-wrap: wrap; }
  .title h1 { font-size: 26px; letter-spacing: -.02em; font-weight: 600; }
  .title p { color: var(--muted); margin-top: 2px; }
  .btn { display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 14px; border-radius: 9px; font-weight: 500; border: 1px solid var(--line); background: var(--panel); cursor: pointer; font: inherit; font-weight: 500; }
  .btn:hover { background: var(--soft); }
  .btn.primary { background: var(--ink); color: #fff; border-color: var(--ink); }
  .btn.primary:hover { background: #27272a; }
  .summary { display: grid; grid-template-columns: repeat(4, 1fr); margin-top: 22px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); }
  .summary > div { padding: 18px 20px; border-right: 1px solid var(--line); }
  .summary > div:last-child { border-right: 0; }
  .summary p { color: var(--muted); font-size: 13px; }
  .summary strong { display: block; font-size: 24px; font-weight: 600; letter-spacing: -.02em; margin-top: 6px; font-family: var(--sans); }
  .summary small { font-size: 12px; color: var(--muted); }
  .meter { height: 6px; border-radius: 999px; background: var(--soft); margin-top: 10px; overflow: hidden; display: flex; }
  .meter span { height: 100%; }
  .panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); margin-top: 18px; overflow: hidden; }
  .toolbar { display: flex; gap: 10px; align-items: center; padding: 12px 14px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
  .search { flex: 1; min-width: 200px; display: flex; align-items: center; gap: 8px; height: 36px; border: 1px solid var(--line); border-radius: 9px; padding: 0 10px; color: var(--muted); }
  .search input { border: 0; outline: 0; font: inherit; flex: 1; background: transparent; color: var(--ink); }
  .filters { display: flex; gap: 6px; }
  .filters button { all: unset; cursor: pointer; height: 30px; padding: 0 11px; border-radius: 999px; border: 1px dashed var(--line); color: var(--muted); font-weight: 500; font-size: 13px; display: inline-flex; align-items: center; }
  .filters button.on { border-style: solid; border-color: var(--ink); color: var(--ink); background: var(--soft); }
  table { width: 100%; border-collapse: collapse; font-size: 13.5px; }
  th { text-align: left; color: var(--muted); font-weight: 500; font-size: 12px; padding: 10px 14px; background: #fbfbfa; border-bottom: 1px solid var(--line); white-space: nowrap; }
  td { padding: 13px 14px; border-bottom: 1px solid var(--line); white-space: nowrap; }
  tbody tr { cursor: pointer; } tbody tr:hover td { background: #fbfbfa; }
  .cust { display: flex; align-items: center; gap: 10px; }
  .cust > span:first-child { width: 30px; height: 30px; flex: none; border-radius: 8px; display: grid; place-items: center; font-weight: 600; font-size: 12px; }
  .cust small { display: block; color: var(--muted); font-size: 12px; }
  .mono { font-family: var(--mono); font-size: 12.5px; }
  .amt { text-align: right; font-family: var(--mono); }
  .badge { display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 8px; border-radius: 6px; font-size: 12px; font-weight: 500; }
  .paid { background: var(--accent-soft); color: var(--accent); } .due { background: var(--amber-soft); color: var(--amber); } .late { background: var(--red-soft); color: var(--red); } .draft { background: var(--soft); color: var(--muted); } .sent { background: var(--blue-soft); color: var(--blue); }
  .check { width: 16px; height: 16px; border: 1.5px solid #c9c9c4; border-radius: 4px; display: inline-block; vertical-align: middle; }
  .foot { display: flex; justify-content: space-between; align-items: center; padding: 12px 14px; color: var(--muted); font-size: 13px; }
  .pager { display: flex; gap: 6px; }
  .side { display: grid; grid-template-columns: 1fr 340px; gap: 18px; }
  .drawer { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); margin-top: 18px; padding: 20px; align-self: start; position: sticky; top: 80px; }
  .drawer h2 { font-size: 16px; font-weight: 600; }
  .drawer .line { display: flex; justify-content: space-between; padding: 10px 0; border-bottom: 1px dashed var(--line); font-size: 13.5px; }
  .drawer .line:last-of-type { border-bottom: 0; }
  .drawer .total { display: flex; justify-content: space-between; font-weight: 600; font-size: 18px; padding-top: 14px; margin-top: 6px; border-top: 1px solid var(--line); }
  .timeline { margin-top: 18px; display: grid; gap: 14px; }
  .timeline div { display: grid; grid-template-columns: 14px 1fr; gap: 10px; font-size: 13px; }
  .timeline i { width: 10px; height: 10px; border-radius: 50%; border: 2px solid var(--accent); margin-top: 4px; }
  .timeline small { display: block; color: var(--muted); font-size: 12px; }
  @media (max-width: 1080px) { .side { grid-template-columns: 1fr; } .drawer { position: static; } }
  @media (max-width: 760px) { .tabs { display: none; } .summary { grid-template-columns: 1fr 1fr; } .summary > div:nth-child(2) { border-right: 0; } .summary > div:nth-child(-n+2) { border-bottom: 1px solid var(--line); } .panel { overflow-x: auto; } }
</style>
</head>
<body>
<header class="bar">
  <span class="brand"><i></i>Ledger</span>
  <nav class="tabs"><a href="#">Tableau de bord</a><a class="on" href="#">Factures</a><a href="#">Clients</a><a href="#">Abonnements</a><a href="#">Rapports</a></nav>
  <div class="right"><button class="btn">Aide</button><span class="org"><span>KA</span>Kora Atelier</span></div>
</header>

<main>
  <div class="title">
    <div><h1>Factures</h1><p>Suivez vos encaissements et relancez en un clic.</p></div>
    <div style="display:flex;gap:8px"><button class="btn">Exporter CSV</button><button class="btn primary">+ Nouvelle facture</button></div>
  </div>

  <div class="summary">
    <div><p>Encaissé ce mois</p><strong>24 860 €</strong><small>sur 31 200 € facturés</small><div class="meter"><span style="width:80%;background:var(--accent)"></span></div></div>
    <div><p>En attente</p><strong>4 120 €</strong><small>7 factures</small><div class="meter"><span style="width:13%;background:var(--amber)"></span></div></div>
    <div><p>En retard</p><strong style="color:var(--red)">2 220 €</strong><small>3 factures · 18 j en moyenne</small><div class="meter"><span style="width:7%;background:var(--red)"></span></div></div>
    <div><p>Délai moyen de paiement</p><strong>12 jours</strong><small>−3 j vs mois dernier</small><div class="meter"><span style="width:40%;background:var(--blue)"></span></div></div>
  </div>

  <div class="side">
    <div class="panel">
      <div class="toolbar">
        <label class="search"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="M21 21l-4-4"/></svg><input placeholder="Rechercher un client, un numéro…" aria-label="Rechercher"></label>
        <div class="filters" role="group" aria-label="Filtrer par statut"><button class="on">Toutes</button><button>Payées</button><button>En attente</button><button>En retard</button><button>Brouillons</button></div>
      </div>
      <table>
        <thead><tr><th><span class="check"></span></th><th>Client</th><th>Numéro</th><th>Émise le</th><th>Échéance</th><th>Statut</th><th style="text-align:right">Montant</th></tr></thead>
        <tbody>
          <tr><td><span class="check"></span></td><td><span class="cust"><span style="background:#e6f4f2;color:#0f766e">MB</span><span>Maison Baobab<small>compta@baobab.co</small></span></span></td><td class="mono">F-2026-0418</td><td>12 oct.</td><td>12 nov.</td><td><span class="badge paid">● Payée</span></td><td class="amt">6 400,00 €</td></tr>
          <tr><td><span class="check"></span></td><td><span class="cust"><span style="background:#e8eefc;color:#1d4ed8">NS</span><span>Nexa Studio<small>finance@nexa.io</small></span></span></td><td class="mono">F-2026-0417</td><td>10 oct.</td><td>10 nov.</td><td><span class="badge sent">● Envoyée</span></td><td class="amt">2 150,00 €</td></tr>
          <tr><td><span class="check"></span></td><td><span class="cust"><span style="background:#fdecea;color:#b42318">AT</span><span>Atlas Transport<small>ap@atlas-t.com</small></span></span></td><td class="mono">F-2026-0409</td><td>28 sept.</td><td>13 oct.</td><td><span class="badge late">● En retard · 17 j</span></td><td class="amt">1 380,00 €</td></tr>
          <tr><td><span class="check"></span></td><td><span class="cust"><span style="background:#fdf3e2;color:#a15c07">LS</span><span>Lumière Santé<small>admin@lumiere.health</small></span></span></td><td class="mono">F-2026-0415</td><td>6 oct.</td><td>20 oct.</td><td><span class="badge due">● Échue bientôt</span></td><td class="amt">980,00 €</td></tr>
          <tr><td><span class="check"></span></td><td><span class="cust"><span style="background:#f1f1ee;color:#71717a">OK</span><span>Okapi Café<small>hello@okapi.cafe</small></span></span></td><td class="mono">F-2026-0419</td><td>—</td><td>—</td><td><span class="badge draft">● Brouillon</span></td><td class="amt">420,00 €</td></tr>
          <tr><td><span class="check"></span></td><td><span class="cust"><span style="background:#e6f4f2;color:#0f766e">VG</span><span>Vega Group<small>billing@vega.group</small></span></span></td><td class="mono">F-2026-0412</td><td>2 oct.</td><td>2 nov.</td><td><span class="badge paid">● Payée</span></td><td class="amt">9 860,00 €</td></tr>
        </tbody>
      </table>
      <div class="foot"><span>6 factures sur 128</span><div class="pager"><button class="btn">Précédent</button><button class="btn">Suivant</button></div></div>
    </div>

    <aside class="drawer" aria-label="Détail de la facture">
      <div style="display:flex;justify-content:space-between;align-items:start"><div><p class="mono" style="color:var(--muted)">F-2026-0409</p><h2>Atlas Transport</h2></div><span class="badge late">En retard</span></div>
      <div style="margin-top:16px">
        <div class="line"><span>Audit logistique · 3 jours</span><span class="mono">1 050,00 €</span></div>
        <div class="line"><span>Rapport et recommandations</span><span class="mono">100,00 €</span></div>
        <div class="line"><span>TVA 20 %</span><span class="mono">230,00 €</span></div>
