      <div style="display:flex;gap:8px;margin-top:16px"><button class="btn primary" style="flex:1;justify-content:center">Relancer le client</button><button class="btn">PDF</button></div>
      <div class="timeline">
        <div><i></i><span>Relance automatique envoyée<small>Il y a 2 jours</small></span></div>
        <div><i></i><span>Facture consultée par le client<small>14 oct. · 09:12</small></span></div>
        <div><i style="border-color:#c9c9c4"></i><span>Facture envoyée<small>28 sept. · 16:40</small></span></div>
      </div>
    </aside>
  </div>
</main>
<script>
  document.querySelectorAll(".filters button").forEach((b) => b.addEventListener("click", () => {
    document.querySelectorAll(".filters button").forEach((x) => x.classList.toggle("on", x === b));
  }));
</script>
